"""Regular output rows with a checked error relative to certified boundaries.

The four boundary polylines are affine in their common axial coordinate between
mandatory knots. Their difference from a new piecewise-linear output boundary
is also affine between the union of both sets of knots. The output knots have
zero error, so checking every original knot bounds the whole boundary, in both
directions. This is not a sparse curve sample or a positional welding tolerance.
"""

OUTPUT_ERROR = .0009  # 1 mm analytic + .9 mm output; reserve .1 mm for roundoff.
MAX_REFINEMENTS = 6
MAX_ROWS = 16384


def construct(g, mandatory, length, target_cell, query, active, *,
              anchors=None, minimum_band=None, transition_cell=None, has_caps=None,
              initial_segments=None):
    if anchors is not None:
        return _anchored(g, mandatory, anchors, length, target_cell, query, active,
                         minimum_band, transition_cell, has_caps, initial_segments)
    if initial_segments is not None:
        raise ValueError('Per-interval initial subdivisions require anchor rows')
    index=g.node('GeometryNodeInputIndex','Regular Bundle axial index').outputs[0]
    metric=g.named('st_bundle_metric','FLOAT')
    base=g.math('MAXIMUM',1.,g.math('CEIL',g.math('DIVIDE',length,g.math('MAXIMUM',target_cell,.01))))
    base_fits=g.compare(base,MAX_ROWS-1,'LESS_EQUAL')

    def residual(segments, geometry):
        step=g.math('DIVIDE',length,segments)
        rank=g.math('MINIMUM',g.math('SUBTRACT',segments,1.),
                    g.math('MAXIMUM',0.,g.math('FLOOR',g.math('DIVIDE',metric,step))))
        start=g.math('MULTIPLY',rank,step)
        finish=g.math('MULTIPLY',g.math('ADD',rank,1.),step)
        t=g.math('DIVIDE',g.math('SUBTRACT',metric,start),step)
        actual,left,right=query(metric),query(start),query(finish)
        errors=[]
        for point,a,b in zip(actual[:4],left[:4],right[:4]):
            chord=g.vector('ADD',a,g.vector('SCALE',g.vector('SUBTRACT',b,a),t))
            errors.append(g.vector('DISTANCE',point,chord))
        maximum=errors[0]
        for other in errors[1:]:maximum=g.math('MAXIMUM',maximum,other)
        return g.stat(geometry,maximum,output='Max')

    ri=g.node('GeometryNodeRepeatInput','Bounded regular Bundle row refinement')
    ro=g.node('GeometryNodeRepeatOutput','Certified regular Bundle row count')
    ro.repeat_items.clear();ro.repeat_items.new('INT','Segments');ro.repeat_items.new('BOOLEAN','Certified')
    ri.pair_with_output(ro)
    g.set(g.switch(active,0,MAX_REFINEMENTS,'INT'),ri.inputs['Iterations'])
    # Cap allocations, but never certify a coarser grid than the requested cell
    # size merely because the initial count exceeds the supported budget.
    g.set(g.math('MINIMUM',base,MAX_ROWS-1),ri.inputs['Segments']);g.set(False,ri.inputs['Certified'])
    n=ri.outputs['Segments'];done=ri.outputs['Certified']
    probe=g.switch(done,mandatory,None,'GEOMETRY','Skip boundary queries after certification')
    error=residual(n,probe)
    okay=g.either(done,g.compare(error,OUTPUT_ERROR,'LESS_EQUAL'))
    doubled=g.math('MINIMUM',MAX_ROWS-1,g.math('MULTIPLY',2.,n))
    g.set(g.switch(okay,doubled,n,'INT'),ro.inputs['Segments']);g.set(okay,ro.inputs['Certified'])
    n=ro.outputs['Segments']
    fits=g.all(base_fits,g.compare(n,MAX_ROWS-1,'LESS_EQUAL'))
    final_error=residual(n,g.switch(active,None,mandatory,'GEOMETRY'))
    valid=g.all(fits,g.compare(final_error,OUTPUT_ERROR,'LESS_EQUAL'))
    line=g.node('GeometryNodeMeshLine','Regular Bundle output rows')
    g.set(g.switch(fits,2,g.math('ADD',n,1.),'INT'),line.inputs['Count'])
    # Force both endpoints exactly. The interior uses one uniform scalar grid.
    fraction=g.math('DIVIDE',index,n)
    table=g.store(line.outputs['Mesh'],'st_bundle_metric',g.math('MULTIPLY',length,fraction))
    table=g.store(table,'st_station_t',fraction)
    # Every emitted chord is part of the perimeter check, not only source knots.
    table=g.store(table,'st_station_knot',True,'BOOLEAN')
    table=g.store(table,'st_bundle_output_error',final_error)
    return table,g.math('ADD',n,1.),valid,final_error


def _anchored(g, mandatory, anchors, length, target_cell, query, active,
              minimum_band, transition_cell, has_caps, initial_segments=None):
    """Uniform subdivisions between exact topology events, with all-knot bounds.

    Anchor positions never move during refinement. The source-knot certificate
    uses the same affine-error argument as the event-free construction, applied
    to each anchor interval. Fine source samples do not become output rows.
    """
    from . import bundle_axis_nodes as axis
    index=g.node('GeometryNodeInputIndex','Event-anchored Bundle interval index').outputs[0]
    metric=g.named('st_bundle_metric','FLOAT')
    count=axis._size(g,anchors)
    positioned=g.node('GeometryNodeSetPosition','Exact event anchor lookup positions')
    g.set(g.store(anchors,'st_bundle_anchor_index',index,'FLOAT'),positioned.inputs['Geometry'])
    g.set(g.xyz(metric),positioned.inputs['Position'])
    points=g.node('GeometryNodeMeshToPoints','All event anchor vertices');points.mode='VERTICES'
    g.set(positioned.outputs['Geometry'],points.inputs['Mesh'])
    ordered=g.node('GeometryNodePointsToCurves','Ordered exact event anchor lookup')
    g.set(points.outputs['Points'],ordered.inputs['Points']);g.set(metric,ordered.inputs['Weight'])
    spans=g.node('GeometryNodeMeshLine','Intervals between critical Bundle events')
    g.set(g.math('MAXIMUM',1.,g.math('SUBTRACT',count,1.)),spans.inputs['Count'])
    a=g.sample(anchors,metric,index,'FLOAT')
    b=g.sample(anchors,metric,g.math('ADD',index,1.),'FLOAT')
    cell=target_cell
    if transition_cell is not None:
        gap=query(g.math('MULTIPLY',.5,g.math('ADD',a,b)))[4]
        near=g.all(has_caps,g.compare(g.math('ABSOLUTE',gap),g.math('MULTIPLY',2.,minimum_band),'LESS_THAN'))
        cell=g.switch(near,cell,g.math('MINIMUM',cell,transition_cell))
    base=g.math('MAXIMUM',1.,g.math('CEIL',g.math('DIVIDE',g.math('SUBTRACT',b,a),g.math('MAXIMUM',.01,cell))))
    if initial_segments is not None:
        base=g.math('MAXIMUM',1.,g.math('CEIL',initial_segments))
    intervals=g.store(spans.outputs['Mesh'],'st_regular_a',a)
    intervals=g.store(intervals,'st_regular_b',b)
    intervals=g.store(intervals,'st_regular_base',base,'INT')
    intervals=g.store(intervals,'st_regular_segments',base,'INT')
    initial_count=g.stat(intervals,base,output='Sum')
    positive=g.stat(intervals,g.compare(b,a,'GREATER_THAN'))

    def errors(state):
        sample=g.node('GeometryNodeSampleCurve','Original knot interval in exact anchor chart')
        sample.mode='LENGTH';sample.data_type='FLOAT'
        g.set(ordered.outputs['Curves'],sample.inputs['Curves'])
        origin=g.sample(anchors,metric,0,'FLOAT')
        g.set(g.math('SUBTRACT',metric,origin),sample.inputs['Length'])
        g.set(g.named('st_bundle_anchor_index','FLOAT'),sample.inputs['Value'])
        interval=g.math('MINIMUM',g.math('SUBTRACT',count,2.),g.math('FLOOR',sample.outputs['Value']))
        interval=g.math('MAXIMUM',0.,interval)
        start=g.sample(state,g.named('st_regular_a','FLOAT'),interval,'FLOAT')
        finish=g.sample(state,g.named('st_regular_b','FLOAT'),interval,'FLOAT')
        segments=g.sample(state,g.named('st_regular_segments'),interval,'INT')
        step=g.math('DIVIDE',g.math('SUBTRACT',finish,start),segments)
        rank=g.math('MAXIMUM',0.,g.math('MINIMUM',g.math('SUBTRACT',segments,1.),
            g.math('FLOOR',g.math('DIVIDE',g.math('SUBTRACT',metric,start),step))))
        low=g.math('ADD',start,g.math('MULTIPLY',rank,step))
        high=g.math('ADD',start,g.math('MULTIPLY',g.math('ADD',rank,1.),step))
        t=g.math('DIVIDE',g.math('SUBTRACT',metric,low),step)
        actual,left,right=query(metric),query(low),query(high)
        errors=[g.vector('DISTANCE',p,g.vector('ADD',a,g.vector('SCALE',g.vector('SUBTRACT',b,a),t)))
                for p,a,b in zip(actual[:4],left[:4],right[:4])]
        error=errors[0]
        for other in errors[1:]:error=g.math('MAXIMUM',error,other)
        return error,interval

    ri=g.node('GeometryNodeRepeatInput','Bounded event-anchored row refinement')
    ro=g.node('GeometryNodeRepeatOutput','Certified local event-interval subdivisions')
    ro.repeat_items.clear();ro.repeat_items.new('GEOMETRY','Intervals');ro.repeat_items.new('BOOLEAN','Certified')
    ro.repeat_items.new('BOOLEAN','Budget')
    ri.pair_with_output(ro)
    g.set(g.switch(active,0,MAX_REFINEMENTS,'INT'),ri.inputs['Iterations'])
    g.set(intervals,ri.inputs['Intervals']);g.set(False,ri.inputs['Certified'])
    g.set(g.compare(initial_count,MAX_ROWS-1,'LESS_EQUAL'),ri.inputs['Budget'])
    state=ri.outputs['Intervals'];done=ri.outputs['Certified']
    error,interval=errors(state)
    probe=g.switch(done,mandatory,None,'GEOMETRY')
    okay=g.either(done,g.compare(g.stat(probe,error,output='Max'),OUTPUT_ERROR,'LESS_EQUAL'))
    failures=g.store(probe,'st_regular_failed_interval',interval,'INT')
    failures=axis._select(g,failures,g.compare(error,OUTPUT_ERROR,'GREATER_THAN'),
                          'Only source knots exceeding the output error allowance')
    locate=g.node('GeometryNodeSetPosition','Failed interval identities as exact lookup coordinates')
    g.set(failures,locate.inputs['Geometry']);g.set(g.xyz(g.named('st_regular_failed_interval')),locate.inputs['Position'])
    failures=locate.outputs['Geometry']
    nearest=g.node('GeometryNodeSampleNearest','Does this interval contain a failed source knot?');nearest.domain='POINT'
    g.set(failures,nearest.inputs['Geometry']);g.set(g.xyz(index),nearest.inputs['Sample Position'])
    owner=g.sample(failures,g.named('st_regular_failed_interval'),nearest.outputs['Index'],'INT')
    refine=g.all(g.compare(axis._size(g,failures),0,'GREATER_THAN','INT'),g.compare(owner,index,kind='INT'))
    segments=g.named('st_regular_segments')
    refined=g.store(state,'st_regular_segments',g.switch(refine,segments,g.math('MULTIPLY',segments,2.),'INT'),'INT')
    fits=g.compare(g.stat(refined,g.named('st_regular_segments'),output='Sum'),MAX_ROWS-1,'LESS_EQUAL')
    g.set(g.switch(fits,state,refined,'GEOMETRY'),ro.inputs['Intervals'])
    g.set(g.all(ri.outputs['Budget'],fits),ro.inputs['Budget'])
    g.set(okay,ro.inputs['Certified'])
    state=ro.outputs['Intervals']
    total=g.math('ADD',1.,g.stat(state,g.named('st_regular_segments'),output='Sum'))
    fits=g.all(positive,ro.outputs['Budget'],g.compare(total,MAX_ROWS,'LESS_EQUAL'))
    final_field,_interval=errors(state)
    final_error=g.stat(g.switch(active,None,mandatory,'GEOMETRY'),final_field,output='Max')
    valid=g.all(fits,g.compare(final_error,OUTPUT_ERROR,'LESS_EQUAL'))
    duplicate=g.node('GeometryNodeDuplicateElements','Uniform rows inside each exact event interval');duplicate.domain='POINT'
    g.set(g.switch(fits,None,state,'GEOMETRY'),duplicate.inputs['Geometry'])
    segments=g.named('st_regular_segments')
    g.set(segments,duplicate.inputs['Amount'])
    fraction=g.math('DIVIDE',duplicate.outputs['Duplicate Index'],segments)
    start=g.named('st_regular_a','FLOAT');finish=g.named('st_regular_b','FLOAT')
    row_metric=g.math('ADD',start,g.math('MULTIPLY',fraction,g.math('SUBTRACT',finish,start)))
    dense=g.store(duplicate.outputs['Geometry'],'st_bundle_metric',row_metric)
    end=g.node('GeometryNodeMeshLine','Exact final event-anchored Bundle station');end.inputs['Count'].default_value=1
    end_geo=g.store(end.outputs['Mesh'],'st_bundle_metric',length)
    table=axis._sorted(g,axis._join(g,dense,end_geo),metric,'Regular event-anchored Bundle output rows')
    table=g.store(table,'st_station_t',g.math('DIVIDE',metric,length))
    table=g.store(table,'st_station_knot',True,'BOOLEAN')
    table=g.store(table,'st_bundle_output_error',final_error)
    table=g.store(table,'st_bundle_event_rows',True,'BOOLEAN')
    return table,total,valid,final_error
